import {
  ConversationEventType,
  type ConversationEvent,
  type MemoryEntryState,
  type MemorySource,
  type SkillCatalog,
} from "../types";
import { formatSkillLabel } from "../utils";

/** Engine sidecar holding LLM-discovered facts; rendered as its own section. */
export const DISCOVERED_FACTS_SLOT = "system.__discovered__";

export interface MemoryRow {
  /** Bare entry name (namespace prefix stripped). */
  name: string;
  /** Fully-qualified slot name, for tooltips and test ids. */
  fullName: string;
  value: unknown;
  source: MemorySource | null;
  description: string | null;
}

export interface MemorySectionView {
  title: string;
  rows: MemoryRow[];
  // Skill sections carry the owning skill's label (one section per skill);
  // "discovered" is the LLM scratchpad; project/system are the shared scopes.
  // The kind drives rendering decisions without matching on the title string.
  kind: "skill" | "project" | "system" | "discovered";
}

export interface SkillMemoryView {
  sections: MemorySectionView[];
}

function bareName(fullName: string): string {
  const separatorIndex = fullName.indexOf(".");
  return separatorIndex === -1 ? fullName : fullName.slice(separatorIndex + 1);
}

function skillPrefix(fullName: string): string {
  const separatorIndex = fullName.indexOf(".");
  return separatorIndex === -1 ? fullName : fullName.slice(0, separatorIndex);
}

function parseDiscoveredFacts(value: unknown): MemoryRow[] {
  if (!Array.isArray(value)) return [];
  const rows: MemoryRow[] = [];
  for (const item of value) {
    if (typeof item !== "object" || item === null) continue;
    const fact = item as Record<string, unknown>;
    if (typeof fact.key !== "string") continue;
    const description = typeof fact.description === "string" ? fact.description : "";
    const capturedBySkill =
      typeof fact.captured_by_skill === "string" ? fact.captured_by_skill : null;
    rows.push({
      name: fact.key,
      fullName: fact.key,
      value: fact.value,
      // Discovered facts are always volunteered by the LLM.
      source: "llm",
      description:
        (capturedBySkill ? `${description} (captured by ${capturedBySkill})` : description) || null,
    });
  }
  // The engine appends facts oldest-first (with oldest-first eviction);
  // reverse so the newest discovery renders at the top of its section.
  return rows.reverse();
}

function isMemoryWrite(event: ConversationEvent): boolean {
  return (
    event.conversationEventType === ConversationEventType.Slot ||
    event.conversationEventType === ConversationEventType.MemorySet ||
    event.conversationEventType === ConversationEventType.MemoryCleared
  );
}

interface RankedRow {
  row: MemoryRow;
  /** Position of the entry's newest write in the conversation, if any. */
  writeIndex: number | undefined;
}

// Written entries first (newest write on top), then filled-but-unwitnessed
// entries, then declared-but-unset ones — each tier keeping contract order
// (the sort is stable and only writeIndex discriminates within tier 0).
function sortRows(ranked: RankedRow[]): MemoryRow[] {
  const tierOf = (entry: RankedRow): number => {
    if (entry.writeIndex !== undefined) return 0;
    return entry.row.value === null || entry.row.value === undefined ? 2 : 1;
  };
  return ranked
    .slice()
    .sort((a, b) => tierOf(a) - tierOf(b) || (b.writeIndex ?? -1) - (a.writeIndex ?? -1))
    .map((entry) => entry.row);
}

function sectionRecency(ranked: RankedRow[]): number {
  return ranked.reduce((newest, entry) => Math.max(newest, entry.writeIndex ?? -1), -1);
}

/**
 * Groups the skill-engine memory map into display sections: one section per
 * skill (keyed by the entry's fully-qualified name prefix), the
 * discovered-facts scratchpad, and the shared project / system scopes.
 *
 * Section titles for skills come from the catalog's display name when
 * available, falling back to a humanized skill id.
 *
 * Recency source: *slotEvents* is the store's `slotRelatedEvents`, which is
 * rebuilt from the full tracker event list on every update — so array order
 * IS tracker write order. The index of an entry's newest memory-write event
 * ranks it; this also covers unstamped writes, which the alternative
 * (`metadata.mantle_write_provenance.position`) would miss. Sections and the
 * rows inside them sort newest-written first; declared-but-unset entries keep
 * contract order below all filled ones. A section's recency is its newest
 * row's write.
 *
 * The engine payload now carries every written field across all skills
 * (including a non-active skill's private entries), so the memory map is the
 * single source of rows; *slotEvents* is used only to rank them by recency.
 */
export function deriveSkillMemoryView(
  memory: Record<string, MemoryEntryState>,
  skillCatalog: SkillCatalog | null,
  slotEvents: readonly ConversationEvent[],
): SkillMemoryView {
  const lastWriteIndexByName = new Map<string, number>();
  slotEvents.forEach((event, index) => {
    if (!isMemoryWrite(event) || !event.name) return;
    lastWriteIndexByName.set(event.name, index);
  });

  const skillGroups = new Map<string, RankedRow[]>();
  const projectRows: RankedRow[] = [];
  const systemRows: RankedRow[] = [];
  let discoveredRows: MemoryRow[] = [];

  const addRow = (fullName: string, row: MemoryRow, scope: MemoryEntryState["scope"]) => {
    const writeIndex = lastWriteIndexByName.get(fullName);
    // Hide entries that were never set: no value now and no witnessed write.
    // A cleared entry (has a write, value now null) keeps its dash row; an
    // entry filled before the inspector joined has a value and stays too.
    const isUnset = row.value === null || row.value === undefined;
    if (isUnset && writeIndex === undefined) return;
    const ranked: RankedRow = { row, writeIndex };
    if (scope === "skill") {
      const prefix = skillPrefix(fullName);
      const rows = skillGroups.get(prefix);
      if (rows) rows.push(ranked);
      else skillGroups.set(prefix, [ranked]);
    } else if (scope === "project") {
      projectRows.push(ranked);
    } else {
      systemRows.push(ranked);
    }
  };

  for (const [fullName, entry] of Object.entries(memory)) {
    if (fullName === DISCOVERED_FACTS_SLOT) {
      discoveredRows = parseDiscoveredFacts(entry.value);
      continue;
    }
    addRow(
      fullName,
      {
        name: bareName(fullName),
        fullName,
        value: entry.value,
        source: entry.source,
        description: entry.description,
      },
      entry.scope,
    );
  }

  const skillTitle = (skillId: string): string =>
    skillCatalog?.[skillId]?.name ?? formatSkillLabel(skillId);

  // Base order (skills in payload order, then Discovered, Project, System) is
  // what renders when nothing was written yet; the stable recency sort below
  // reorders only sections that saw writes.
  const ordered: { section: MemorySectionView; recency: number }[] = [];
  for (const [prefix, ranked] of skillGroups) {
    ordered.push({
      section: { title: skillTitle(prefix), rows: sortRows(ranked), kind: "skill" },
      recency: sectionRecency(ranked),
    });
  }
  if (discoveredRows.length > 0) {
    ordered.push({
      section: { title: "Discovered", rows: discoveredRows, kind: "discovered" },
      recency: lastWriteIndexByName.get(DISCOVERED_FACTS_SLOT) ?? -1,
    });
  }
  if (projectRows.length > 0) {
    ordered.push({
      section: { title: "Project", rows: sortRows(projectRows), kind: "project" },
      recency: sectionRecency(projectRows),
    });
  }
  if (systemRows.length > 0) {
    ordered.push({
      section: { title: "System", rows: sortRows(systemRows), kind: "system" },
      recency: sectionRecency(systemRows),
    });
  }
  ordered.sort((a, b) => b.recency - a.recency);

  return { sections: ordered.map((entry) => entry.section) };
}
